<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {api,post,query,requestId as newRequestId,contextVersion,isCancelled,datetime} from '../lib/api'
import {isParent,isAdmin,campuses,currentCampusId} from '../lib/state'
import {useResource,loadStudents,studentOptions,openDialog,notify} from '../lib/ui'
import {attachmentUrl} from '../mobile/endpoints'
import {serviceBase} from '../mobile/platform'
import type {Attachment} from '../lib/types'
import PageHeader from '../components/PageHeader.vue'
import SoftSelect from '../components/SoftSelect.vue'
import LoadState from '../components/LoadState.vue'
import AttachmentList from '../components/AttachmentList.vue'
import AppIcon from '../components/AppIcon.vue'
interface Preset{id:number;campusId:number;campusName:string;name:string;points:number;enabled:boolean;version:number}
interface Prize{id:number;campusId:number;campusName:string;name:string;pointsCost:number;stock:number;enabled:boolean;version:number;image:Attachment|null}
interface Redemption{id:number;studentId:number;studentName:string;prizeName:string;pointsCost:number;teacherName:string;createdAt:string;attachments:Attachment[]}
const studentId=ref<string|number>(''),busy=ref(false),error=ref(''),receipt=ref<Attachment|null>(null),presetId=ref<string|number>('')
const resource=useResource(async()=>{const [students,presets,prizes,records]=await Promise.all([loadStudents(),api<Preset[]>('/point-presets'),api<Prize[]>('/reward-prizes'),api<Redemption[]>('/prize-redemptions'+query({studentId:studentId.value}))]);return {students,presets,prizes,records}},[studentId])
const child=computed(()=>resource.data.value?.students.find(s=>s.id===Number(studentId.value)))
const configOptions=computed(()=>campuses.value.filter(c=>currentCampusId.value===null||c.id===currentCampusId.value).map(c=>({value:c.id,label:c.name})))
const childPresets=computed(()=>resource.data.value?.presets.filter(p=>p.enabled&&p.campusId===child.value?.campusId)||[])
const editor=ref(false),editId=ref<number|null>(null),editVersion=ref(0),campusId=ref<string|number>(''),prizeName=ref(''),cost=ref('10'),stock=ref('0'),enabled=ref('yes'),cover=ref<Attachment|null>(null)
const controller=new AbortController();onBeforeUnmount(()=>controller.abort());let request='',fingerprint=''
watch([contextVersion,studentId],()=>{receipt.value=null;presetId.value='';error.value='';request='';fingerprint='';editor.value=false})
async function act(fn:()=>Promise<unknown>,message:string){if(busy.value)return;const version=contextVersion.value;busy.value=true;error.value='';try{await fn();if(version!==contextVersion.value||controller.signal.aborted)return;notify(message);await resource.refresh()}catch(e){if(version===contextVersion.value&&!controller.signal.aborted&&!isCancelled(e))error.value=(e as Error).message}finally{if(version===contextVersion.value)busy.value=false}}
function requestFor(body:unknown){const value=JSON.stringify(body);if(!request||fingerprint!==value){request=newRequestId();fingerprint=value}return request}
async function photo(event:Event,kind:'cover'|'receipt',record?:Redemption){const input=event.target as HTMLInputElement,file=input.files?.[0],campus=kind==='cover'?Number(campusId.value):(record?resource.data.value?.students.find(s=>s.id===record.studentId)?.campusId:child.value?.campusId);if(!file||!campus)return;await act(async()=>{if(!file.type.startsWith('image/'))throw new Error('请选择图片文件');const data=new FormData();data.append('file',file);const uploaded=await api<Attachment>('/files',{method:'POST',body:data,campusId:campus,signal:controller.signal});if(record)await api(`/prize-redemptions/${record.id}/photos`,{method:'POST',body:{attachmentIds:[uploaded.id]},signal:controller.signal});else if(kind==='cover')cover.value=uploaded;else receipt.value=uploaded},record?'兑换照片已记录':'照片已上传');input.value=''}
async function award(){if(!child.value||!presetId.value)return;const body={studentId:child.value.id,presetId:Number(presetId.value)};if(await openDialog({title:'确认固定积分奖励',description:`为${child.value.name}按所选后台规则发放积分。`,confirm:'确认奖励',submit:()=>post('/point-awards',{...body,requestId:requestFor(body)}),success:'积分已发放'})){request='';resource.refresh()}}
async function redeem(item:Prize){if(!child.value)return;const student=child.value,body={studentId:student.id,prizeId:item.id,expectedVersion:item.version,attachmentIds:receipt.value?[receipt.value.id]:[]};if(await openDialog({title:'确认兑换奖品',description:`${student.name}兑换「${item.name}」，扣除${item.pointsCost}积分并减少1件库存。请确认已实际发放，可附兑换照片。`,confirm:'已发放，确认兑换',submit:()=>post('/prize-redemptions',{...body,requestId:requestFor(body)}),success:'兑换已记录，积分与库存已更新'})){receipt.value=null;request='';resource.refresh()}}
function edit(item?:Prize){editId.value=item?.id||null;editVersion.value=item?.version||0;campusId.value=item?.campusId||currentCampusId.value||configOptions.value[0]?.value||'';prizeName.value=item?.name||'';cost.value=String(item?.pointsCost||10);stock.value=String(item?.stock||0);enabled.value=item?.enabled===false?'no':'yes';cover.value=item?.image||null;editor.value=true}
async function savePrize(){await act(async()=>{await api(editId.value?`/reward-prizes/${editId.value}`:'/reward-prizes',{method:editId.value?'PUT':'POST',body:{campusId:Number(campusId.value),name:prizeName.value,pointsCost:Number(cost.value),stock:Number(stock.value),enabled:enabled.value==='yes',imageFileId:cover.value?.id||null,expectedVersion:editVersion.value}});editor.value=false},'奖品已保存')}
async function editPreset(item?:Preset){if(await openDialog({title:item?'编辑固定奖励':'新增固定奖励',fields:[...(!item?[{key:'campusId',label:'校区',type:'select' as const,required:true,options:configOptions.value}]:[]),{key:'name',label:'奖励名称',required:true},{key:'points',label:'奖励积分',type:'number',min:1,max:100,required:true},{key:'enabled',label:'是否启用',type:'select',options:[{value:'yes',label:'启用'},{value:'no',label:'停用'}]}],initial:{campusId:currentCampusId.value||configOptions.value[0]?.value,name:item?.name||'',points:item?.points||2,enabled:item?.enabled===false?'no':'yes'},submit:v=>api(item?`/point-presets/${item.id}`:'/point-presets',{method:item?'PUT':'POST',body:{...v,points:Number(v.points),enabled:v.enabled==='yes',expectedVersion:item?.version||0}}),success:'固定奖励已保存'}))resource.refresh()}
</script>
<template><PageHeader title="积分与奖品" subtitle="让每一份努力，换成孩子期待的小小奖励。"><button v-if="isAdmin" class="btn primary" @click="edit()">新增奖品</button></PageHeader><p v-if="error" class="reward-error" role="alert">{{error}}</p><section class="panel reward-filter"><SoftSelect v-model="studentId" :disabled="busy" :options="[{value:'',label:'选择孩子'},...studentOptions(resource.data.value?.students||[])]" aria-label="奖励学生" /><strong v-if="child">可用 {{child.points}} 积分</strong><button class="text-btn" @click="resource.refresh">刷新</button></section><LoadState :loading="resource.loading.value" :error="resource.error.value" @retry="resource.refresh"><section v-if="!isParent" class="panel reward-section"><h2>固定积分奖励</h2><p class="form-hint">作业完成、日小结发布按系统规则自动奖励；这里用于老师确认的额外表现。</p><div class="reward-filter"><SoftSelect v-model="presetId" :disabled="busy" :options="childPresets.map(p=>({value:p.id,label:`${p.name} +${p.points}分`}))" placeholder="先选择孩子，再选择奖励" /><button class="btn primary" :disabled="busy||!child||!presetId" @click="award">确认奖励</button></div><button v-if="isAdmin" class="text-btn" @click="editPreset()">新增固定奖励</button><div v-if="isAdmin" class="preset-list"><button v-for="p in resource.data.value?.presets" :key="p.id" class="preset-chip" @click="editPreset(p)">{{p.campusName}} · {{p.name}} +{{p.points}} {{p.enabled?'':'（停用）'}}</button></div></section>
<section v-if="editor&&isAdmin" class="panel reward-section"><h2>{{editId?'编辑奖品':'新增奖品'}}</h2><label class="field"><span>校区</span><SoftSelect v-model="campusId" :disabled="busy||!!editId" :options="configOptions" @change="cover=null" /></label><label class="field"><span>奖品名称</span><input v-model="prizeName" :disabled="busy" maxlength="100" /></label><div class="reward-edit-grid"><label class="field"><span>兑换积分</span><input v-model="cost" :disabled="busy" type="number" min="1" step="1" /></label><label class="field"><span>库存</span><input v-model="stock" :disabled="busy" type="number" min="0" step="1" /></label></div><SoftSelect v-model="enabled" :disabled="busy" :options="[{value:'yes',label:'上架'},{value:'no',label:'下架'}]" /><AttachmentList v-if="cover" :files="[cover]" /><label class="btn secondary reward-upload">上传奖品图片<input type="file" accept="image/*" :disabled="busy||!campusId" @change="photo($event,'cover')" /></label><div class="row-actions"><button class="btn primary" :disabled="busy||!campusId||!prizeName" @click="savePrize">保存奖品</button><button class="btn secondary" :disabled="busy" @click="editor=false">取消</button></div></section>
<section v-if="!isParent&&child" class="panel reward-section"><h2>本次兑换照片（可选）</h2><AttachmentList v-if="receipt" :files="[receipt]" /><label class="btn secondary reward-upload">拍照记录<input type="file" accept="image/*" capture="environment" :disabled="busy" @change="photo($event,'receipt')" /></label><button v-if="receipt" class="text-btn" @click="receipt=null">移除本次照片</button></section>
<h2 class="reward-heading">可选奖品</h2><div class="prize-grid"><article v-for="item in resource.data.value?.prizes" :key="item.id" class="panel prize-card"><img v-if="item.image" class="prize-cover" :src="attachmentUrl(serviceBase,item.image.url)" :alt="item.name" /><AttachmentList v-if="item.image" :files="[item.image]" /><AppIcon v-else name="Trophy" :size="36" /><h3>{{item.name}}</h3><p>{{item.campusName}} · 库存 {{item.stock}}</p><strong>{{item.pointsCost}} <small>积分</small></strong><span v-if="!item.enabled" class="badge gray">已下架</span><div class="row-actions"><button v-if="!isParent" class="btn primary" :disabled="busy||!child||child.campusId!==item.campusId||!item.enabled||item.stock<1||child.points<item.pointsCost" @click="redeem(item)">兑换并发放</button><button v-if="isAdmin" class="text-btn" @click="edit(item)">编辑</button></div></article></div><p v-if="!resource.data.value?.prizes.length" class="compact-empty">校区暂未设置奖品。</p><p v-if="isParent" class="form-hint">可与孩子一起选奖品，由负责老师核对积分并现场兑换。</p><section class="panel reward-section"><h2>兑换记录</h2><article v-for="record in resource.data.value?.records" :key="record.id" class="redemption-row"><h3>{{record.studentName}} · {{record.prizeName}}</h3><p>使用 {{record.pointsCost}} 积分 · {{record.teacherName}} · {{datetime(record.createdAt)}}</p><AttachmentList :files="record.attachments" /><label v-if="!isParent" class="text-btn reward-upload">补充兑换照片<input type="file" accept="image/*" capture="environment" :disabled="busy" @change="photo($event,'receipt',record)" /></label></article><p v-if="!resource.data.value?.records.length" class="compact-empty">暂无兑换记录。</p></section></LoadState></template>
<style scoped>.prize-cover{width:100%;height:170px;object-fit:contain;border-radius:17px;background:#f5f6fa}.reward-filter{padding:18px;display:flex;align-items:center;gap:15px;margin-bottom:20px;flex-wrap:wrap}.reward-filter .soft-select{flex:1;min-width:150px}.reward-section{padding:25px;margin-bottom:22px}.reward-section h2,.reward-heading{font-size:19px;margin-bottom:17px}.prize-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr));gap:20px;margin-bottom:24px}.prize-card{padding:24px;display:flex;flex-direction:column;gap:14px}.prize-card h3{font-size:18px}.prize-card p,.redemption-row p{font-size:13px;color:var(--text-secondary);line-height:1.8}.prize-card>strong{font-size:28px}.prize-card small{font-size:13px;font-weight:400}.reward-upload{display:inline-flex;margin:12px 0;cursor:pointer}.reward-upload input{display:none}.reward-edit-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.redemption-row{padding:20px 0;border-bottom:1px solid var(--border)}.redemption-row h3{font-size:16px;margin-bottom:8px}.reward-error{background:#fff0ef;color:#b23e36;border-radius:15px;padding:17px;margin:15px 0}.preset-list{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}.preset-chip{background:#f2f5fa;border-radius:12px;padding:10px;font-size:12px;color:var(--text-secondary)}@media(max-width:600px){.reward-section{padding:20px}.reward-filter{padding:15px}.reward-edit-grid{grid-template-columns:1fr}}</style>
